'use client';
import { FormEvent,useState } from 'react';
import Link from 'next/link';
import { api } from '@/lib/api';
export default function SecurityPage(){const[error,setError]=useState('');async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);const next=String(f.get('newPassword'));if(next!==String(f.get('repeat'))){setError('Новые пароли не совпадают');return;}try{await api('/auth/change-password',{method:'POST',body:JSON.stringify({currentPassword:f.get('currentPassword'),newPassword:next})});window.location.href='/login';}catch(c){setError(c instanceof Error?c.message:'Ошибка');}}return <div className="settings-narrow"><div className="section-title"><div><h1>Безопасность аккаунта</h1><p className="muted">После смены пароля все активные входы завершаются.</p></div><Link className="button ghost" href="/settings">Назад</Link></div>{error&&<div className="error-box">{error}</div>}<section className="card"><form onSubmit={submit}><label>Текущий пароль<input name="currentPassword" type="password" autoComplete="current-password" required/></label><label>Новый пароль<input name="newPassword" type="password" minLength={10} autoComplete="new-password" required/></label><label>Повторите новый пароль<input name="repeat" type="password" minLength={10} autoComplete="new-password" required/></label><button className="button">Изменить пароль</button></form></section></div>}
